void setup_floppy_track_format(int track) {
    struct format_params {
        int sectors_per_track;
        int interleave;
        int sector_position;
        int sector_number;
        int is_sector_busy;
        int stretch_applied;
        int kernel_data;
        int kernel_length;
    } params;

    params.sectors_per_track = 0;
    params.interleave = 0;
    params.sector_position = 0;
    params.sector_number = 0;
    params.is_sector_busy = 0;
    params.stretch_applied = 0;
    params.kernel_data = 0;
    params.kernel_length = 0;

    // Calculate sectors per track and interleave based on formatting requirements
    params.sectors_per_track = 18; // Example value, could vary by floppy type
    params.interleave = 1;         // Default interleave value

    for (int i = 0; i < params.sectors_per_track; i++) {
        params.sector_position = i * params.interleave;

        // Check if sector is busy
        if (params.is_sector_busy) {
            continue;
        }

        // Adjust sector number if stretch is applied
        if (params.stretch_applied) {
            params.sector_number = (params.sector_position + track * params.sectors_per_track) % params.sectors_per_track;
        } else {
            params.sector_number = params.sector_position;
        }

        // Assign kernel data and length for the raw command
        params.kernel_data = track * 10 + params.sector_number;
        params.kernel_length = 512; // Example sector size
    }
}

void setup_floppy_track_format(int track) {
    struct format_params {
